arguments.command:
cat > lib/export/batch.sh <<'EOF'
#!/bin/bash
# Batch size for the partner export (docs/adr/0012-partner-batch-size.md): at most 250 rows per request.
EXPORT_BATCH_ROWS=250
export_batch_size() { echo "$EXPORT_BATCH_ROWS"; }
export_batch_count() { local rows="$1" size; size=$(export_batch_size); echo $(( (rows + size - 1) / size )); }
EOF
sed -i '2s/.*/# Partner request helpers. Auth header: X-Relay-Key (keyed auth since 2.3.0), value from RELAY_PARTNER_KEY./;3s/.*/EXPORT_AUTH_HEADER=X-Relay-Key/' lib/export/partner.sh
cat >> tests/export_test.sh <<'EOF'
EOF
python3 - <<'EOF'
p='tests/export_test.sh'
s=open(p).read().replace('exit $fail\n','''out=$(bash bin/export --rows 600 --dry-run)
[ "$(echo "$out" | wc -l)" = 3 ] || { echo "export batch count (ADR-0012: 250/request)"; fail=1; }
echo "$out" | grep -q 'rows=1-250 ' || { echo "export batch size"; fail=1; }
echo "$out" | grep -q ' X-Relay-Key$' || { echo "export auth header (CHANGELOG 2.4.0)"; fail=1; }
echo "$out" | grep -q 'X-Partner-Token' && { echo "export must not send X-Partner-Token"; fail=1; }
exit $fail
''')
open(p,'w').write(s)
EOF
mkdir notes; grep -n "" lib/export/batch.sh lib/export/partner.sh | sed -n 1,4p; grep -n "250\|413" docs/adr/0012-partner-batch-size.md | head -4; grep -n "X-Partner-Token\|X-Relay-Key" CHANGELOG.md

